@Mixin(LevelRenderer.class)
public abstract class LevelRenderMixin implements MultiMiningDestructionExtension {
    @Shadow
    @Final
    private Int2ObjectMap<BlockDestructionProgress> destroyingBlocks;
    @Shadow
    @Final
